    strings = lines[1:n+1]

    if n == 0:
        return '0\n'

    def get_freq_count(s):
        """Returns tuple of sorted character counts"""
        return tuple(sorted(s))

    def is_sorted(s):
        return list(s) == sorted(s)

    def is_equal_freq(s1, s2):
        return len(s1) == len(s2) and get_freq_count(s1) == get_freq_count(s2)

    FONT_LIMIT = 1337

    # Group by sorted multiset
    from collections import defaultdict
    groups = defaultdict(list)
    sorted_strings = {}  # store sorted version for each str

    for s in strings:
        freq = get_freq_count(s)
