def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    competitors = []
    for i in range(n):
        si, ri = map(int, lines[1 + i].split())
        competitors.append((si, ri, i + 1))

    # Filter: remove points that are strictly dominated by any other point
    # Point i is dominated by j if sj >= si AND rj >= ri (strict in at least one)
    dominated = [False] * n
    for i in range(n):
        for j in range(n):
            if i != j:
                if competitors[j][0] >= competitors[i][0] and competitors[j][1] >= competitors[i][1]:
                    if competitors[j][0] > competitors[i][0] or competitors[j][1] > competitors[i][1]:
                        dominated[i] = True
                        break

    valid_points = []
    for i in range(n):
        if not dominated[i]:
            si, ri, idx = competitors[i]
            valid_points.append((1.0/si, 1.0/ri, idx))

    if not valid_points:
        return ""

    if len(valid_points) <= 2:
        return ' '.join(str(idx) for _, _, idx in sorted(valid_points, key=lambda x: x[2])) + ' \n'

    # Sort by x, then y for convex hull
    valid_points.sort()

    # Monotone chain algorithm for lower convex hull (keeps collinear points on the hull)
    stack = []
    for x, y, idx in valid_points:
        while len(stack) >= 2:
            x1, y1, _ = stack[-2]
            x2, y2, _ = stack[-1]
            # Cross product: (x2-x1, y2-y1) × (x-x1, y-y1)
            cp = (x2 - x1) * (y - y1) - (x - x1) * (y2 - y1)
            # For lower hull: pop if right turn (cp < 0), keep straight lines (cp = 0)
            if cp < 0:
                stack.pop()
            else:
                break
        stack.append((x, y, idx))

    # Return indices in sorted order (they're already sorted)
    result = []
    for x, y, idx in stack:
        result.append(str(idx))

    return ' '.join(result) + '\n'

