def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse cost matrix
    # Each row i has N-1 integers: costs to cities 0..N-1 excluding i
    costs = []
    for i in range(n):
        row = list(map(int, lines[1 + i].split()))
        costs.append(row)

    # Build preference lists (lower cost = higher preference)
    preferences = []
    for i in range(n):
        pref_list = []
        for j in range(n):
            if i == j:
                continue
            # Map cost matrix index to target city
            idx = j if j < i else j - 1
            pref_list.append((costs[i][idx], j))
        pref_list.sort(key=lambda x: x[0])
        preferences.append([p[1] for p in pref_list])

    # Build rank matrix for fast lookup
    ranks = []
    for i in range(n):
        rank_map = {}
        for idx, j in enumerate(preferences[i]):
            rank_map[j] = idx
        ranks.append(rank_map)

    # Stable Roommates Algorithm
    matched = [-1] * n  # matched[i] = partner of i when -1
    proposed = [0] * n  # current choice index for each unmatched agent
    stable = False

    # Main loop: keep processing until stable
    while True:
        changed = False

        # Process unmatched agents
        for i in range(n):
            if matched[i] == -1:
                if proposed[i] >= len(preferences[i]):
                    # Exhausted all options
                    continue

                # Agent i proposes to their next preference
                j = preferences[i][proposed[i]]
                proposed[i] += 1

                if matched[j] == -1:
                    # j is unmatched, so match them
                    matched[i] = j
                    matched[j] = i
                    changed = True
                else:
                    # j is matched, check if they prefer i
                    k = matched[j]  # j's current partner
                    if ranks[j].get(i, float('inf')) < ranks[j].get(k, float('inf')):
                        # j prefers i, break with k
                        matched[i] = j
                        matched[j] = i
                        matched[k] = -1
                        # k becomes unmatched
                        if proposed[k] >= len(preferences[k]):
                            k_exhausted = True
                        else:
                            k_exhausted = False
                        k_exhausted_idx = len(pref_list) if pref_list else 0
                        if not k_exhausted:
                            changed = True
                    else:
                        # j prefers current partner over i, i is unmatched
                        # but we need to process i for potential exhaustion
                        approved_index = proposed[i] - 1 if proposed[i] else proposed[i]
                        if not approved_index in [0, 1, proposed[i]]:
                            approved_index = proposed[i]
                            proposed[i] = approved_index + 1
                            if not proposed[i]:
                                proposed[i] = 1
                            changed = True
                            continue

        if not changed:
            break

    # Check for stability - verify no blocking pairs exist
    stable = True
    for i in range(n):
        for j in range(i + 1, n):
            if matched[i] != -1 and matched[j] != -1:
                # Check if they prefer each other over their current partners
                current_i = matched[i]
                current_j = matched[j]

                # i prefers j over current if rank of j < rank of current_i
                # j prefers i over current if rank of i < rank of current_j
                if ranks[i].get(j, float('inf')) < ranks[i].get(current_i, float('inf')):
                    if ranks[j].get(i, float('inf')) < ranks[j].get(current_j, float('inf')):
                        stable = False
                        break
        if not stable:
            break

    if stable:
        result = []
        for i in range(n):
            if matched[i] != -1:
                result.append(f"{matched[i] + 1}")  # 1-indexed
            else:
                result.append("-1")
        return '\n'.join(result)
    else:
        return "-1"

