class FenwickTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (size + 2)

    def update(self, i, delta):
        while i <= self.size:
            self.tree[i] += delta
            i += i & (-i)

    def query(self, i):
        result = 0
        while i > 0:
            result += self.tree[i]
            i -= i & (-i)
        return result

    def range_query(self, l, r):
        if l > r:
            return 0
        return self.query(r) - self.query(l - 1)

def compute_delta(n, l, r, al, ar, val, pos):
    """Compute how inversion count changes when swapping positions l and r (0-indexed)"""

    if l >= r:
        return 0

    al, ar = val[l], val[r]

    if al == ar:
        return 0

    delta = 0

    # Direct swap effect
    if al > ar:
        delta -= 1
    else:
        delta += 1

    # Count elements between positions l and r with values between al and ar
    low = min(al, ar) + 1
    high = max(al, ar) - 1

    left_of_l = l
    for k in range(l + 1, r):
        v = val[k]
        if low <= v <= high:
            delta += 1
        else:
            delta -= 1

    return delta

