    operations = []
    for i in range(1, q + 1):
        parts = input_data[i].split()
        l, r = map(int, parts)
        operations.append((l, r))

    val = [0] * n
    pos = [0] * (n + 1)
    for i in range(n):
        val[i] = i + 1
        pos[i + 1] = i  # 0-indexed position of value i (1-indexed value)

    total_inv = 0
    outputs = []

    for l, r in operations:
        l -= 1  # 0-indexed
        r -= 1

        if l >= r:
            outputs.append(str(total_inv) + '\n')
            continue

        if l > r:
            l, r = r, l

        al = val[l]
        ar = val[r]

        if al == ar:
            outputs.append(str(total_inv) + '\n')
            continue

        # Calculate delta
        delta = 0

        # Direct inversion between al and ar
        if al > ar:
            delta -= 1
        else:
            delta += 1

        # Check elements between positions l and r
        low = min(al, ar)
        high = max(al, ar)

        for k in range(l + 1, r):
            v = val[k]
            if v > ar and v < al:
                if al > ar:
                    delta += 1
                else:
                    delta -= 1
            elif v < ar and v > al:
                if al > ar:
                    delta -= 1
                else:
                    delta += 1

        # Check elements before position l (for interaction with both al and ar)
        for k in range(l):
            v = val[k]
            if al > v and ar > v:
                # Both greater than v -> neither is inversion before, now one is
                # If al < ar now: al > v becomes inversion for al, ar > v becomes inversion for ar
                delta += 1
            elif v < al and v > ar:
                delta -= 1

        # Check elements after position r
        for k in range(r + 1, n):
            v = val[k]
            if v > al and v > ar:
                delta -= 1

        total_inv += delta

        # Update
        val[l], val[r] = ar, al
        pos[al], pos[ar] = r, l

        outputs.append(str(total_inv) + '\n')

    return ''.join(outputs)

