def solve_tree(n, a, adj, alice_start, bob_start):
    # Simulate the game
    visited = [False] * (n + 1)
    alice_visited = set()
    bob_visited = set()
    alice_visited.add(alice_start)
    bob_visited.add(bob_start)
    visited[alice_start] = True
    visited[bob_start] = True

    alice_current = alice_start
    bob_current = bob_start

    total_chocolates = a[alice_start - 1] + a[bob_start - 1]

    alice_turn = True

    while True:
        if not alice_visited and not bob_visited:
            break

        if alice_turn:
            valid_moves = []
            for neighbor in adj[alice_current]:
                if not visited[neighbor]:
                    valid_moves.append(neighbor)

            if not valid_moves:
                alice_turn = False
                continue

            # Choose best next move (greedy on highest chocolates)
            alice_next = -1
            max_val = -1
            for node in valid_moves:
                if a[node - 1] > max_val:
                    max_val = a[node - 1]
                    alice_next = node

            alice_next -= 1
            # ... rest of simulation
            alice_turn = False
        else:
            # Bob's turn
            valid_moves = []
            for neighbor in adj[bob_current]:
                if not visited[neighbor]:
                    valid_moves.append(neighbor)

            if not valid_moves:
                alice_turn = True
                continue

            bob_next = -1
            max_val = -1
            for node in valid_moves:
                if a[node - 1] > max_val:
                    max_val = a[node - 1]
                    bob_next = node

            bob_next -= 1
            visited[bob_next] = True
            bob_visited.add(bob_next)
            total_chocolates += a[bob_next - 1]
            bob_turn = True

    return total_chocolates

