    import sys
    original = pytest.TestReport.from_item_and_call

    class WrappedReport:
        def __init__(self, underlying):
            self._underlying = underlying
            for attr in dir(underlying):
                if not attr.startswith('__'):
                    setattr(self, attr, getattr(underlying, attr))

