def get_prime_factors(num):
    i = 2
    factors = {}
    while i * i <= num:
        while num % i == 0:
            factors[i] = factors.get(i, 0) + 1
            num //= i
        i += 1
    if num > 1:
        factors[num] = 1
    return factors

