    n, m = map(int, lines[0].split())

    attempts = []
    for line in lines[1:]:
        parts = line.split()
        if len(parts) >= 2:
            attempts.append((parts[0], int(parts[1])))

    n_left = n // 2
    n_right = n - n_left

    # Build match vector for left half
    left_dict = {}
    for i in range(1 << n_left):
        left_code = format(i, f'0{n_left}b')

        match_counts = []
        for attempt_str, count in attempts:
            m_count = sum(1 for j in range(n_left) if left_code[j] == attempt_str[j])
            match_counts.append(m_count)

        if all(match_counts[j] <= attempts[j][1] for j in range(m)):
            key = tuple(match_counts)
            left_dict[key] = left_dict.get(key, 0) + 1

    # Build match vector for right half
    right_dict = {}
    for i in range(1 << n_right):
        right_code = format(i, f'0{n_right}b')

        match_counts = []
        for attempt_str, count in attempts:
            m_count = sum(1 for j in range(n_right) if right_code[j] == attempt_str[n_left + j])
            match_counts.append(m_count)

        if all(match_counts[j] <= attempts[j][1] for j in range(m)):
            key = tuple(match_counts)
            right_dict[key] = right_dict.get(key, 0) + 1

    # Combine
    ans = 0
    for left_key, left_count in left_dict.items():
        target = tuple(attempts[j][1] - left_key[j] for j in range(m))
        if target in right_dict:
